import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.semanticweb.owlapi.apibinding.OWLManager;
import org.semanticweb.owlapi.model.*;
import org.semanticweb.owlapi.model.parameters.*;
import org.semanticweb.owlapi.formats.*;
import org.semanticweb.owlapi.io.*;
import org.semanticweb.owlapi.util.SimpleIRIMapper;
public class ProbeManagerBehavior {
 static void row(String key,Object...values){System.out.println(key+"\t"+Arrays.toString(values));}
 static OWLOntology load(OWLOntologyManager m,String s,boolean annotations)throws Exception{return m.loadOntologyFromOntologyDocument(new StringDocumentSource(s,IRI.create("urn:source:"+UUID.randomUUID()),new FunctionalSyntaxDocumentFormat(),null),new OWLOntologyLoaderConfiguration().setLoadAnnotationAxioms(annotations));}
 static OWLAxiom ax(OWLOntologyManager m,String s){return m.getOWLDataFactory().getOWLDeclarationAxiom(m.getOWLDataFactory().getOWLClass(IRI.create("urn:"+s)));}
 static OWLAxiom ann(OWLOntologyManager m){return m.getOWLDataFactory().getOWLAnnotationAssertionAxiom(m.getOWLDataFactory().getRDFSLabel(),IRI.create("urn:S"),m.getOWLDataFactory().getOWLLiteral("value"));}
 static String names(OWLOntologyManager m){return m.ontologies().map(o->o.getOntologyID().getOntologyIRI().map(Object::toString).orElse("anonymous")+":"+o.getAxiomCount()).sorted().toList().toString();}
 public static void main(String[]args)throws Exception {
  row("source",uk.ac.manchester.cs.owl.owlapi.OWLOntologyManagerImpl.class.getProtectionDomain().getCodeSource().getLocation());
  var m=OWLManager.createOWLOntologyManager();var o=load(m,"Ontology(<urn:filtered>)",false);var a=ax(m,"A");
  row("empty-batch",m.applyChangesAndGetDetails(List.of()).getChangeEffect());
  row("inverse",m.applyChangesAndGetDetails(List.of(new AddAxiom(o,a),new RemoveAxiom(o,a))).getChangeEffect(),o.getAxiomCount());
  var details=m.applyChangesAndGetDetails(List.of(new AddAxiom(o,a),new RemoveAxiom(o,a),new AddAxiom(o,ann(m))));
  row("inverse-before-unsuccess",details.getChangeEffect(),details.getEnactedChanges().size(),o.getAxiomCount(),o.containsAxiom(a));
  m.removeAxiom(o,a);var old=o.getOntologyID();row("rename",m.applyChange(new SetOntologyID(o,new OWLOntologyID(IRI.create("urn:renamed")))),m.addAxiom(o,ann(m)),o.getAxiomCount());
  var reused=m.createOntology(old);row("old-id-config-retained",m.addAxiom(reused,ann(m)),reused.getAxiomCount());
  m.removeOntology(reused);reused=m.createOntology(old);row("remove-config-retained",m.addAxiom(reused,ann(m)),reused.getAxiomCount());
  var lm=OWLManager.createOWLOntologyManager();var lo=lm.createOntology(IRI.create("urn:listeners"));var events=new ArrayList<String>();
  lm.addImpendingOntologyChangeListener(cs->events.add("impending:"+cs.size()+":"+lo.getAxiomCount()));
  lm.addOntologyChangeProgessListener(new OWLOntologyChangeProgressListener(){public void begin(int s){events.add("begin:"+s+":"+lo.getAxiomCount());}public void appliedChange(OWLOntologyChange c){events.add("applied:"+c.getClass().getSimpleName()+":"+lo.getAxiomCount());}public void end(){events.add("end:"+lo.getAxiomCount());}});
  lm.addOntologyChangeListener(cs->events.add("changed:"+cs.size()+":"+lo.getAxiomCount()));
  var la=ax(lm,"L");row("listener-batch-result",lm.applyChanges(List.of(new AddAxiom(lo,la),new AddAxiom(lo,la),new RemoveAxiom(lo,la))));row("listener-batch-events",events);events.clear();
  var collide=lm.createOntology(IRI.create("urn:collision"));lm.addAxiom(collide,ax(lm,"Other"));events.clear();
  try{lm.applyChanges(List.of(new AddAxiom(lo,la),new SetOntologyID(lo,collide.getOntologyID())));}catch(Exception e){row("listener-thrown",e.getClass().getSimpleName(),lo.getAxiomCount(),events);}events.clear();
  var vm=OWLManager.createOWLOntologyManager();var vo=vm.createOntology(IRI.create("urn:veto"));var ve=new ArrayList<String>();
  vm.addImpendingOntologyChangeListener(cs->{ve.add("impending");throw new OWLOntologyChangeVetoException(cs.get(0).getChangeData(),"veto");});vm.addOntologyChangesVetoedListener((cs,e)->ve.add("vetoed:"+cs.size()));vm.addOntologyChangeListener(cs->ve.add("changed"));row("veto",vm.addAxiom(vo,ax(vm,"V")),vo.getAxiomCount(),ve);
  var rm=OWLManager.createOWLOntologyManager();var ro=rm.createOntology(IRI.create("urn:reentrant"));var re=new ArrayList<String>();boolean[] nested={false};
  rm.addOntologyChangeListener(cs->{re.add("callback:"+ro.getAxiomCount());if(!nested[0]){nested[0]=true;rm.addAxiom(ro,ax(rm,"Nested"));}});row("reentrant",rm.addAxiom(ro,ax(rm,"Outer")),ro.getAxiomCount(),re);
  Path folder=Path.of(args[0]);Path af=folder.resolve("import-a.ofn"),bf=folder.resolve("import-b.ofn");Files.writeString(af,"Ontology(<urn:import-a> Declaration(Class(<urn:A>)))");Files.writeString(bf,"not functional");
  var im=OWLManager.createOWLOntologyManager();var existing=im.createOntology(IRI.create("urn:existing"));im.addAxiom(existing,ax(im,"Existing"));im.getIRIMappers().add(new SimpleIRIMapper(IRI.create("urn:import-a"),IRI.create(af.toFile())));im.getIRIMappers().add(new SimpleIRIMapper(IRI.create("urn:import-b"),IRI.create(bf.toFile())));
  String root="Ontology(<urn:root> Import(<urn:import-a>) Import(<urn:import-b>) Declaration(Class(<urn:Root>)))";
  try{load(im,root,false);}catch(Exception e){row("import-failure",e.getClass().getSimpleName(),names(im));}
  row("retained-import-config",im.addAxiom(im.getOntology(IRI.create("urn:import-a")),ann(im)),names(im));Files.writeString(bf,"Ontology(<urn:import-b> Declaration(Class(<urn:B>)))");
  try{var retried=load(im,root,false);row("retry-after-fixed-import",names(im),retried.importsClosure().count(),retried.importsDeclarations().count());}catch(Exception e){row("retry-after-fixed-import-error",e.getClass().getSimpleName(),names(im));}
  var sm=OWLManager.createOWLOntologyManager();sm.getIRIMappers().add(new SimpleIRIMapper(IRI.create("urn:import-a"),IRI.create(af.toFile())));try{load(sm,"Ontology(<urn:bad-root> Import(<urn:import-a>) NOT_SYNTAX)",true);}catch(Exception e){row("root-syntax-failure",e.getClass().getSimpleName(),names(sm));}
 }
}

import java.io.*;
import java.util.*;
import org.semanticweb.owlapi.apibinding.OWLManager;
import org.semanticweb.owlapi.model.*;
import org.semanticweb.owlapi.formats.*;
import org.semanticweb.owlapi.io.*;
public class ProbeWriterBehavior {
 static class Sink extends Writer {StringBuilder text=new StringBuilder();int writes,flushes,closes;final String mode;Sink(String m){mode=m;}public void write(char[]b,int o,int n)throws IOException {writes++;for(int i=0;i<n;i++){if(text.length()==20){if(mode.equals("write-io"))throw new IOException("write20");if(mode.equals("write-runtime"))throw new IllegalStateException("write20");}text.append(b[o+i]);}}public void flush()throws IOException {flushes++;if(mode.equals("flush-io"))throw new IOException("flush");}public void close()throws IOException{closes++;if(mode.equals("close-io"))throw new IOException("close");}}
 static class Bytes extends OutputStream {int bytes,flushes,closes;public void write(int b)throws IOException{if(bytes==20)throw new IOException("bytes20");bytes++;}public void flush(){flushes++;}public void close(){closes++;}}
 static String desc(Throwable e){return e.getClass().getSimpleName()+":"+e.getMessage()+";cause="+(e.getCause()==null?"none":e.getCause().getClass().getSimpleName());}
 public static void main(String[]args)throws Exception {
 System.out.println("source\t"+org.semanticweb.owlapi.util.AbstractOWLStorer.class.getProtectionDomain().getCodeSource().getLocation());
 var m=OWLManager.createOWLOntologyManager();var o=m.createOntology(IRI.create("urn:writer"));m.addAxiom(o,m.getOWLDataFactory().getOWLDeclarationAxiom(m.getOWLDataFactory().getOWLClass(IRI.create("urn:A"))));
 for(var f:List.of(new FunctionalSyntaxDocumentFormat(),new RDFXMLDocumentFormat(),new OWLXMLDocumentFormat(),new TurtleDocumentFormat()))for(var mode:List.of("normal","write-io","write-runtime","flush-io","close-io")){
  var sink=new Sink(mode);var t=new OWLOntologyDocumentTarget(){public Optional<Writer> getWriter(){return Optional.of(sink);}};String result="OK";try{m.saveOntology(o,f,t);}catch(Throwable e){result=desc(e);}System.out.println(f.getKey()+"\t"+mode+"\t"+result+"\tchars="+sink.text.length()+"\twrites="+sink.writes+"\tflushes="+sink.flushes+"\tcloses="+sink.closes);
 }
 var stream=new Bytes();String result="OK";try{m.saveOntology(o,new FunctionalSyntaxDocumentFormat(),new OWLOntologyDocumentTarget(){public Optional<OutputStream> getOutputStream(){return Optional.of(stream);}});}catch(Throwable e){result=desc(e);}System.out.println("stream\t"+result+"\tbytes="+stream.bytes+"\tflushes="+stream.flushes+"\tcloses="+stream.closes);
 var target=new StringDocumentTarget();m.saveOntology(o,new FunctionalSyntaxDocumentFormat(),target);int n=target.toString().length();m.saveOntology(o,new FunctionalSyntaxDocumentFormat(),target);System.out.println("reuse\t"+n+"\t"+target.toString().length());
 }
}

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.semanticweb.owlapi.apibinding.OWLManager;
