import org.semanticweb.owlapi.formats.*;
import org.semanticweb.owlapi.model.*;
import org.eclipse.rdf4j.rio.*;
import org.eclipse.rdf4j.rio.helpers.JSONLDSettings;
import no.hasmac.jsonld.loader.*;
import no.hasmac.jsonld.document.*;
public class ProbeJsonLdBehavior {
 static int maximum, calls;static String tag;static boolean cyclic;
 static String outcome(Throwable e){StringBuilder s=new StringBuilder();for(int i=0;e!=null&&i<12;i++,e=e.getCause()){s.append(e.getClass().getSimpleName()).append(":").append(e.getMessage()).append(" |");}return s.toString().replace('\n',' ');}
 static Document response(URI u,DocumentLoaderOptions options) throws no.hasmac.jsonld.JsonLdError {calls++;if(calls>300)throw new IllegalStateException("probe bound");String next;int i;if(u.toString().equals("https://schema.org/")){i=maximum;}else{i=Integer.parseInt(u.getPath().substring(u.getPath().lastIndexOf('/')+1));}next=i<maximum?"{\"@context\":\"https://probe.example/"+tag+"/"+(cyclic?1:i+1)+"\"}":"{\"@context\":{\"x\":\"urn:x:\"}}";var d=JsonDocument.of(new StringReader(next));d.setDocumentUrl(u);return d;}
 static void run(String id,int count,String first,Boolean systemSecure,boolean formatOff){tag=id;maximum=count;calls=0;System.clearProperty(JSONLDSettings.SECURE_MODE.getKey());System.setProperty(JSONLDSettings.DOCUMENT_LOADER_CACHE.getKey(),"false");if(systemSecure!=null)System.setProperty(JSONLDSettings.SECURE_MODE.getKey(),systemSecure.toString());var f=new RDFJsonLDDocumentFormat();if(formatOff)f.setParameter(JSONLDSettings.SECURE_MODE,false);String text="{\"@context\":\""+first+"\",\"@id\":\"urn:s\",\"@type\":\"http://www.w3.org/2002/07/owl#Class\"}";try{var o=OWLManager.createOWLOntologyManager().loadOntologyFromOntologyDocument(new StringDocumentSource(text,IRI.create("urn:jsonld:"+id),f,null));System.out.println(id+"\tOK\tcalls="+calls+"\taxioms="+o.getAxiomCount());}catch(Throwable e){System.out.println(id+"\tFAIL\tcalls="+calls+"\t"+outcome(e));}}
 public static void main(String[]args)throws Exception {
  var router=(SchemeRouter)SchemeRouter.defaultInstance();router.set("https",ProbeJsonLdBehavior::response);router.set("http",ProbeJsonLdBehavior::response);router.set("file",(u,o)->{throw new IllegalStateException("probe denies file");});
  var parser=Rio.createParser(RDFFormat.JSONLD);System.out.println("selected\t"+parser.getClass().getName()+"\t"+parser.getClass().getProtectionDomain().getCodeSource().getLocation());
  System.out.println("processor\t"+no.hasmac.jsonld.JsonLd.class.getProtectionDomain().getCodeSource().getLocation());
  System.out.println("supported\t"+parser.getSupportedSettings().stream().map(RioSetting::getKey).sorted().toList());
  System.out.println("defaults\tsecure="+parser.getParserConfig().get(JSONLDSettings.SECURE_MODE)+"\tcache="+parser.getParserConfig().get(JSONLDSettings.DOCUMENT_LOADER_CACHE)+"\twhitelist="+parser.getParserConfig().get(JSONLDSettings.WHITELIST).size());
  run("default-unlisted",1,"https://probe.example/default-unlisted/1",null,false);
  run("default-listed",1,"https://schema.org/",null,false);
  run("format-off-unlisted",1,"https://probe.example/format-off-unlisted/1",null,true);
  run("system-off-chain13",13,"https://probe.example/system-off-chain13/1",false,false);
  run("system-off-chain257",257,"https://probe.example/system-off-chain257/1",false,false);
  run("system-off-chain258",258,"https://probe.example/system-off-chain258/1",false,false);
  System.clearProperty(JSONLDSettings.SECURE_MODE.getKey());System.clearProperty(JSONLDSettings.DOCUMENT_LOADER_CACHE.getKey());
 }
}

