import { createRequire } from 'node:module';import { pathToFileURL } from 'node:url';
const root='${OWLAPI_SOURCE}';process.env.TEMP="${GAP_WORKSPACE}/temporary";process.env.TMP=process.env.TEMP;const req=createRequire(root+'/package.json');const pw=req('playwright');
const {xmlParserAdapter}=await import(pathToFileURL(root+'/internal/parsing/xml/xmlParserAdapter.js'));
const {prepareXml}=await import(pathToFileURL(root+'/internal/parsing/xml/xmlEntityPolicy.js'));
const {OWLOntologyLoaderConfiguration}=await import(pathToFileURL(root+'/model/owlOntologyLoaderConfiguration.js'));
const configuration=new OWLOntologyLoaderConfiguration();
const cases=[['valid','<r xmlns:x="urn:x"><x:c/></r>'],['duplicate-attribute','<r a="1" a="2"/>'],['control-character','<r>\u0001</r>'],['xml11','<?xml version="1.1"?><r/>'],['depth110','<r>'.repeat(110)+'</r>'.repeat(110)],['empty-prefix','<r xmlns:p=""><p:c/></r>']];
const results={node:{version:process.version,xml:[]},browsers:{}};
for(const [id,text]of cases){try{await xmlParserAdapter.parseXml(text,configuration);results.node.xml.push({id,result:'OK'});}catch(e){results.node.xml.push({id,result:e.name,code:e.code});}}
for(const name of ['chromium','firefox','webkit']){let browser;try{browser=await pw[name].launch({headless:true,timeout:10000});const page=await browser.newPage();let network=0;await page.route('**/*',route=>{network++;return route.abort();});await page.setContent('<!doctype html><iframe></iframe>');results.browsers[name]=await page.evaluate(items=>({userAgent:navigator.userAgent,xml:items.map(([id,text])=>{const d=new DOMParser().parseFromString(text,'application/xml');return{id,result:d.documentElement.localName==='parsererror'?'parsererror':'OK',root:d.documentElement.localName,ns:d.documentElement.namespaceURI};}),nativeSignal:Object.getOwnPropertyDescriptor(AbortSignal.prototype,'aborted').get.call(new AbortController().signal),crossRealmSignal:Object.getOwnPropertyDescriptor(AbortSignal.prototype,'aborted').get.call(new (document.querySelector('iframe').contentWindow.AbortController)().signal),duckSignal:(()=>{try{return Object.getOwnPropertyDescriptor(AbortSignal.prototype,'aborted').get.call({aborted:false});}catch(e){return e.name;}})()}),cases.map(([id,text])=>[id,prepareXml(text,configuration)]));results.browsers[name].networkRequests=network;}catch(e){results.browsers[name]={error:e.message};}finally{if(browser)await browser.close();}}
console.log(JSON.stringify(results));

