public class ProbeJsonLdDefaultChain {
 static List<String> urls;static int limit,calls;
 static Document response(URI uri,DocumentLoaderOptions options) throws no.hasmac.jsonld.JsonLdError {
  if(++calls>30)throw new IllegalStateException("probe bound");
  int i=urls.indexOf(uri.toString());if(i<0)throw new IllegalStateException("unlisted route");
  String text=i+1<limit?"{\"@context\":\""+urls.get(i+1)+"\"}":"{\"@context\":{\"x\":\"urn:x:\"}}";
  var d=JsonDocument.of(new StringReader(text));d.setDocumentUrl(uri);return d;
 }
 public static void main(String[]args)throws Exception {
  System.clearProperty(JSONLDSettings.SECURE_MODE.getKey());System.clearProperty(JSONLDSettings.DOCUMENT_LOADER_CACHE.getKey());System.clearProperty(JSONLDSettings.WHITELIST.getKey());
  var p=Rio.createParser(RDFFormat.JSONLD);urls=new ArrayList<>(p.getParserConfig().get(JSONLDSettings.WHITELIST));Collections.sort(urls);limit=Integer.parseInt(args[0]);if(limit>urls.size())throw new IllegalArgumentException("probe exceeds whitelist");
  var r=(SchemeRouter)SchemeRouter.defaultInstance();r.set("http",ProbeJsonLdDefaultChain::response);r.set("https",ProbeJsonLdDefaultChain::response);r.set("file",(u,o)->{throw new IllegalStateException("file denied");});
  String text="{\"@context\":\""+urls.get(0)+"\",\"@id\":\"urn:s\",\"@type\":\"http://www.w3.org/2002/07/owl#Class\"}";
  try{var o=OWLManager.createOWLOntologyManager().loadOntologyFromOntologyDocument(new StringDocumentSource(text,IRI.create("urn:default-chain:"+limit),new RDFJsonLDDocumentFormat(),null));System.out.println("OK\tlimit="+limit+"\tcalls="+calls+"\taxioms="+o.getAxiomCount()+"\tsecure="+p.getParserConfig().get(JSONLDSettings.SECURE_MODE)+"\tcache="+p.getParserConfig().get(JSONLDSettings.DOCUMENT_LOADER_CACHE));}
  catch(Throwable e){System.out.println("FAIL\tlimit="+limit+"\tcalls="+calls+"\t"+e);}
 }
}

