public class ProbeJsonLdCache {
 static int calls,version=1;static Set<String> failures=new HashSet<>();
 static Document response(URI uri,DocumentLoaderOptions options)throws JsonLdError {
  if(++calls>20)throw new IllegalStateException("probe bound");
  if(failures.remove(uri.toString()))throw new JsonLdError(JsonLdErrorCode.LOADING_DOCUMENT_FAILED,"injected");
  var d=JsonDocument.of(new StringReader("{\"@context\":{\"x\":\"urn:v"+version+":\"}}"));d.setDocumentUrl(uri);return d;
 }
 static void run(String name,String uri,boolean formatOff){
  int before=calls;var format=new RDFJsonLDDocumentFormat();if(formatOff)format.setParameter(JSONLDSettings.DOCUMENT_LOADER_CACHE,false);
  try{var o=OWLManager.createOWLOntologyManager().loadOntologyFromOntologyDocument(new StringDocumentSource("{\"@context\":\""+uri+"\",\"@id\":\"x:s\",\"@type\":\"http://www.w3.org/2002/07/owl#Class\"}",IRI.create("urn:cache:"+name),format,null));System.out.println(name+"\tOK\tcalls="+(calls-before)+"\tclasses="+o.classesInSignature().map(c->c.getIRI().toString()).sorted().toList());}
  catch(Throwable e){System.out.println(name+"\t"+e.getClass().getSimpleName()+"\tcalls="+(calls-before));}
 }
