  System.setProperty(JSONLDSettings.DOCUMENT_LOADER_CACHE.getKey(),"false");run("system-cache-bypass",a,false);System.clearProperty(JSONLDSettings.DOCUMENT_LOADER_CACHE.getKey());run("cache-restored-old-value",a,false);
  System.setProperty(JSONLDSettings.SECURE_MODE.getKey(),"false");run("unlisted-warm",u,false);System.clearProperty(JSONLDSettings.SECURE_MODE.getKey());run("secure-rejects-warm-cache",u,false);
